const input = $input.first().json;
const urls = (input.urls_fotos || '').split(',').map(u => u.trim()).filter(u => u.length > 0);
const descricao = (input.mensagem_descritiva || '').trim();

return urls.map((url, i) => ({
  json: {
    url: url,
    foto_numero: i + 1,
    total_fotos: urls.length,
    content: (i === 0 && descricao) ? descricao : '',
    conversation_id: input.conversation_id,
    url_chatwoot: input.url_chatwoot,
    id_conta_chatwoot: input.id_conta_chatwoot
  }
}));

const triggerData = $('Trigger - Recebe Dados').first().json;
const urls = (triggerData.urls_fotos || '').split(',').map(u => u.trim()).filter(u => u.length > 0);

return [{
  json: {
    status: 'sucesso',
    fotos_enviadas: urls.length,
    mensagem: `${urls.length} foto(s) do imóvel enviada(s) com sucesso para o lead.`
  }
}];

