parameters.jsCode:
const input = $input.first().json;
const telefone = (input.telefone_cliente || '').replace(/\+/g, '');
const conversationId = input.conversation_id || '';
let properties = [];

try {
  properties = typeof input.imoveis_json === 'string' 
    ? JSON.parse(input.imoveis_json) 
    : input.imoveis_json;
} catch (e) {
  properties = [];
}

if (!Array.isArray(properties)) properties = [properties];

const defaultImage = 'https://img.apresenta.me/BcHdDoIgGADQt_Eu-CmXtnFB2YUm33SV98YcYtNYHwvh6TtHMuNIdmAfR9RqaJankmlHUoZEmZlydYa_AXcJ_EwQYbv7OsS_3V2T0JXWyxL23N4QMYhJNHWR61i8oIVSeP4QWzdDqMD-8N3b6iiicaGDXUccv2agatFRdEJj7cQ0yeMiY-IP.jpg';

// Helper to format price
const formatPreco = (p) => p ? 'R$ ' + (p/1000).toFixed(0) + ' mil' : 'Consulte';

// VALIDATION: WhatsApp carousels require minimum 2 cards, maximum 10
if (properties.length === 0) {
  return [{
    json: {
      error: true,
      errorMessage: 'Nenhum imovel fornecido para o carrossel',
      shouldSendCarousel: false,
      propertiesCount: 0,
      carouselPayload: null,
      cacheData: null,
      cacheKey: 'carousel:' + telefone,
      phone: telefone,
      conversationId: conversationId
    }
  }];
}

if (properties.length === 1) {
  const p = properties[0];
  const imageUrl = (p.imagens && Array.isArray(p.imagens)) ? (p.imagens.find(url => !url.includes('youtu')) || defaultImage) : (p.foto_capa || p.imagem_url || p.foto_url || defaultImage);
  const tipo = p.tipo_imovel || p.tipo || 'Imovel';
  const bairro = p.bairro || '';
  const preco = formatPreco(p.preco);
  const tamanho = p.tamanho_m2 || p.tamanho || '?';
  const quartos = p.quartos || '?';
  const suite = p.suite || p.suites || 0;
  const garagem = p.garagem || 0;

  let caption = '🏠 ' + tipo + '\n';
  caption += '📐 ' + tamanho + 'm² | 💰 ' + preco + '\n';
  caption += '🛏️ ' + quartos + ' quartos';
  if (suite > 0) caption += ' | 🛁 ' + suite + ' suite';
  if (garagem > 0) caption += ' | 🚗 ' + garagem + ' vaga';
  caption += '\n📍 ' + bairro;

  const singleImagePayload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: telefone,
    type: 'image',
    image: {
      link: imageUrl,
      caption: caption
    }
  };

  const cacheData = {
    timestamp: Date.now(),
    properties: [{
      index: 1,
      id: p.id || null,
      listing_id: p.listing_id || p.id || 'N/A',
      tipo: tipo,
      bairro: bairro,
      endereco: p.endereco || '',
      numero: p.numero || '',
      preco: p.preco || 0,
      tamanho_m2: tamanho,
      quartos: quartos,
      banheiros: p.banheiros || 0,
      suite: suite,
      garagem: garagem,
      imagem_url: imageUrl,
      descricao: p.descricao_resumida || p.descricao || ''
    }]
  };

  return [{
    json: {
      error: false,
      shouldSendCarousel: false,
      shouldSendImage: true,
      propertiesCount: 1,
      carouselPayload: singleImagePayload,
      cacheData: cacheData,
      cacheKey: 'carousel:' + telefone,
      phone: telefone,
      conversationId: conversationId
    }
  }];
}

// 2+ properties - build carousel normally
const propertiesSent = properties.slice(0, 10).map((p, i) => {
  return {
    index: i + 1,
    id: p.id || null,
    listing_id: p.listing_id || p.id || 'N/A',
    tipo: p.tipo_imovel || p.tipo || 'Imovel',
    bairro: p.bairro || '',
    endereco: p.endereco || '',
    numero: p.numero || '',
    preco: p.preco || 0,
    tamanho_m2: p.tamanho_m2 || p.tamanho || '?',
    quartos: p.quartos || '?',
    banheiros: p.banheiros || 0,
    suite: p.suite || p.suites || 0,
    garagem: p.garagem || 0,
    imagem_url: (p.imagens && Array.isArray(p.imagens)) ? (p.imagens.find(url => !url.includes('youtu')) || defaultImage) : (p.foto_capa || p.imagem_url || p.foto_url || defaultImage),
    descricao: p.descricao_resumida || p.descricao || ''
  };
});

const cards = propertiesSent.map((p, i) => {
  const preco = formatPreco(p.preco);

  // Build body text with emojis (max 160 chars)
  let bodyText = '🏠 ' + p.tipo + '\n';
