const tipoFollowUp = $('Dados do Lead').item.json.tipo_followUp;
const nome = $('Dados do Lead').item.json.LeadNome;

// Saudação dinâmica baseada no horário de Brasília
const hora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: 'numeric', hour12: false });
const horaNum = parseInt(hora);
const saudacao = horaNum >= 5 && horaNum < 12 ? 'Bom dia' : horaNum >= 12 && horaNum < 18 ? 'Boa tarde' : 'Boa noite';

let mensagem = '';
let tipoParaAtualizar = '';

switch (tipoFollowUp) {
  case 'followUp1h':
    mensagem = `${nome} você ficou com alguma dúvida?`;
    tipoParaAtualizar = 'followUp1h';
    break;

  case 'followUp12h':
    mensagem = `Oi ${nome}! Posso te ajudar a esclarecer mais alguma coisa sobre o empreendimento?`;
    tipoParaAtualizar = 'followUp12h';
    break;

  case 'followUp24h':
    mensagem = `${nome} você ainda tem interesse neste imóvel que foi apresentado?`;
    tipoParaAtualizar = 'followUp24h';
    break;

  case 'followUp3D':
    mensagem = `${nome} faz sentido o lançamento que foi apresentado pra você? Se não, você ainda busca algum tipo de imóvel nesta região? Pois ainda tenho outros imóveis que posso te apresentar.`;
    tipoParaAtualizar = 'followUp3D';
    break;

  case 'followUp7D':
    mensagem = `${nome} estamos sem nos falar já faz um tempo. Porém apareceu uma oportunidade na região que você estava buscando. Você ainda tem interesse?`;
    tipoParaAtualizar = 'followUp7D';
    break;

  case 'finalizado':
    mensagem = `${nome} como não obtive seu retorno, vou encerrar o atendimento. Mas quando você estiver interessado em adquerir imóveis na região, pode sempre entrar em contato conosco por aqui mesmo: 21 96483-0018 Sabino.`;
    tipoParaAtualizar = 'finalizado';
    break;

  default:
    mensagem = '';
    tipoParaAtualizar = '';
}

return [{
  json: {
    mensagem,
    tipoParaAtualizar
  }
}];

