const nomeLead = $('Entrada de Dados').first().json.nomeLead;
const telefone = $('Entrada de Dados').first().json.IdConversa;
let resumo = $('Entrada de Dados').first().json.resumo_da_conversa || '';

const LIMITE_WHATSAPP = 4096;

// Monta o cabeçalho (parte fixa da mensagem)
const cabecalho = `*Nova Solicitação de Atendimento*

*Nome:* ${nomeLead}
*Telefone:* ${telefone}

*Resumo do atendimento:*
`;

// Calcula espaço disponível para o resumo
const espacoDisponivel = LIMITE_WHATSAPP - cabecalho.length - 10;

if (resumo.length > espacoDisponivel) {
  resumo = resumo.substring(0, espacoDisponivel) + '...';
}

const mensagem = cabecalho + resumo;

return [{ json: { mensagem } }];

const nomeLead = $('Entrada de Dados').first().json.nomeLead;
const telefone = $('Entrada de Dados').first().json.IdConversa;

const mensagem = `*Nova Solicitação de Atendimento*\n\n*Nome:* ${nomeLead}\n*Telefone:* ${telefone}`;

return [{ json: { mensagem } }];

// Code Node: Identificar e Formatar Telefones Globais (MODO BLINDADO / SAFE MODE)
// Prioridade máxima para leads do Brasil. Risco Zero de Falsos Positivos Internacionais.

// ========================================
// FUNÇÃO COMPLETA DE FORMATAÇÃO DE TELEFONE
// ========================================
function processPhoneNumber(phone) {
    if (!phone) {
        return { isValid: false, error: "Sem telefone", original: phone };
    }

    let cleaned = phone.toString().trim();
    const hasPlus = cleaned.startsWith('+');
    cleaned = cleaned.replace(/\D/g, '');

    if (cleaned.startsWith('0') && !cleaned.startsWith('00')) {
        cleaned = cleaned.replace(/^0+/, '');
    }

    if (cleaned.startsWith('00') && cleaned.length > 2) {
        cleaned = cleaned.substring(2);
    }

    // Lista de DDIs (resumida para leitura, mas atende global)
    const commonDDIs = {
        '1': 'EUA/Canadá', '7': 'Rússia', '20': 'Egito', '27': 'África do Sul',
        '30': 'Grécia', '31': 'Holanda', '32': 'Bélgica', '33': 'França',
        '34': 'Espanha', '351': 'Portugal', '352': 'Luxemburgo', '353': 'Irlanda',
        '354': 'Islândia', '355': 'Albânia', '356': 'Malta', '357': 'Chipre',
        '358': 'Finlândia', '359': 'Bulgária', '36': 'Hungria', '370': 'Lituânia',
        '371': 'Letônia', '372': 'Estônia', '373': 'Moldávia', '374': 'Armênia',
        '375': 'Belarus', '376': 'Andorra', '377': 'Mônaco', '378': 'San Marino',
        '379': 'Vaticano', '380': 'Ucrânia', '381': 'Sérvia', '382': 'Montenegro',
        '385': 'Croácia', '386': 'Eslovênia', '387': 'Bósnia', '389': 'Macedônia',
        '39': 'Itália', '40': 'Romênia', '41': 'Suíça', '420': 'República Tcheca',
        '421': 'Eslováquia', '423': 'Liechtenstein', '43': 'Áustria', '44': 'Reino Unido',
        '45': 'Dinamarca', '46': 'Suécia', '47': 'Noruega', '48': 'Polônia',
        '49': 'Alemanha', '500': 'Ilhas Malvinas', '501': 'Belize', '502': 'Guatemala',
        '503': 'El Salvador', '504': 'Honduras', '505': 'Nicarágua', '506': 'Costa Rica',
        '507': 'Panamá', '508': 'São Pedro', '509': 'Haiti', '51': 'Peru',
        '52': 'México', '53': 'Cuba', '54': 'Argentina', '55': 'Brasil',
        '56': 'Chile', '57': 'Colômbia', '58': 'Venezuela', '590': 'Guadalupe',
        '591': 'Bolívia', '592': 'Guiana', '593': 'Equador', '594': 'Guiana Francesa',
        '595': 'Paraguai', '596': 'Martinica', '597': 'Suriname', '598': 'Uruguai',
        '599': 'Antilhas', '60': 'Malásia', '61': 'Austrália', '62': 'Indonésia',
        '63': 'Filipinas', '64': 'Nova Zelândia', '65': 'Singapura', '66': 'Tailândia',
        '81': 'Japão', '82': 'Coreia do Sul', '84': 'Vietnã', '86': 'China',
        '90': 'Turquia', '91': 'Índia', '92': 'Paquistão', '93': 'Afeganistão',
        '94': 'Sri Lanka', '95': 'Myanmar', '98': 'Irã'
    };

    const validDDDs = [
        '11', '12', '13', '14', '15', '16', '17', '18', '19', 
        '21', '22', '24', '27', '28', 
        '31', '32', '33', '34', '35', '37', '38', 
        '41', '42', '43', '44', '45', '46', 
        '47', '48', '49', 
        '51', '53', '54', '55', 
        '61', '62', '63', '64', '65', '66', '67', '68', '69', 
        '71', '73', '74', '75', '77', '79', 
        '81', '82', '83', '84', '85', '86', '87', '88', '89', 
        '91', '92', '93', '94', '95', '96', '97', '98', '99'
    ];

    let countryCode = null;
    let isExplicitlyInternational = false;

    // REGRA DE OURO 1 e 2: Se for maior que 12 ou tiver sinal de +, confiamos no DDI
    if (hasPlus || cleaned.length >= 12) {
        for (let len = 3; len >= 1; len--) {
            const possibleDDI = cleaned.substring(0, len);
            if (commonDDIs[possibleDDI] || possibleDDI === '55') {
                countryCode = possibleDDI;
                isExplicitlyInternational = (countryCode !== '55');
                break;
            }
        }
    }

    // REGRA DE OURO 3: O BLOQUEIO BRASILEIRO (Safe Mode)
    // Se não for garantido como gringo, não tiver +, e tiver 10 ou 11 dígitos, é Brasil!
    if (!isExplicitlyInternational && !hasPlus && (cleaned.length === 10 || cleaned.length === 11)) {
        const ddd = cleaned.substring(0, 2);
        if (validDDDs.includes(ddd)) {
            countryCode = '55'; // Força Brasil
            cleaned = '55' + cleaned;
        }
    }

    const isBrazil = countryCode === '55';
    const isInternational = !isBrazil && countryCode !== null;

    // ========================================
    // PROCESSAMENTO BRASIL (Sem margem de erro)
    // ========================================
    if (isBrazil) {
        let brazilNumber = cleaned.substring(2);

        // Adiciona 9º dígito se for celular de 10 dígitos (incomum hoje, mas previne falhas)
        if (brazilNumber.length === 10) {
            const ddd = brazilNumber.substring(0, 2);
            const firstDigit = brazilNumber.substring(2, 3);
            if (validDDDs.includes(ddd) && ['6', '7', '8', '9'].includes(firstDigit)) {
                brazilNumber = ddd + '9' + brazilNumber.substring(2);
            }
        }

        if (brazilNumber.length !== 10 && brazilNumber.length !== 11) {
            return { isValid: false, original: phone, withDDI: cleaned, withoutDDI: cleaned };
        }

        const ddd = brazilNumber.substring(0, 2);
        const number = brazilNumber.substring(2);
        const isMobile = brazilNumber.length === 11;

        let formatted = isMobile 
            ? `(${ddd}) ${number.substring(0, 5)}-${number.substring(5)}`
            : `(${ddd}) ${number.substring(0, 4)}-${number.substring(4)}`;

        return {
            isValid: true,
            original: phone,
            formatted: formatted,
            withDDI: '55' + brazilNumber,
            withoutDDI: brazilNumber,
            country: 'Brasil'
        };
    }

    // ========================================
    // PROCESSAMENTO INTERNACIONAL
    // ========================================
    if (isInternational) {
        const localNumber = cleaned.substring(countryCode.length);
        let formatted = `+${countryCode} ${localNumber}`;

        return {
            isValid: true,
            original: phone,
            formatted: formatted,
            withDDI: cleaned,
            withoutDDI: localNumber,
            country: commonDDIs[countryCode] || 'Desconhecido'
        };
    }

    // Fallback: Se for impossível processar, devolve o original
    return {
        isValid: false,
        original: phone,
        formatted: phone,
        withDDI: cleaned, 
        withoutDDI: cleaned,
        country: 'Desconhecido'
    };
}


// ========================================
// PROCESSAMENTO PRINCIPAL (INPUT)
// ========================================

// Pega os dados vindos do nó "Buscar 1 Lead Pendente"
const inputData = $input.first().json;

// Extrai apenas o número do telefone para processar
const phoneInput = inputData.telefone || null;
const result = processPhoneNumber(phoneInput);

// ========================================
// FORMATAÇÃO DO NOME (Primeiro Nome Capitalizado)
// ========================================
let primeiroNome = null;

if (inputData.cliente) {
    // Quebra o nome inteiro pelos espaços
    const nomePartes = inputData.cliente.toString().trim().split(' ');
    let primeiroNomeCru = nomePartes[0];

    // Deixa a primeira letra Maiúscula e o resto Minúscula
    if (primeiroNomeCru.length > 0) {
        primeiroNome = primeiroNomeCru.charAt(0).toUpperCase() + primeiroNomeCru.slice(1).toLowerCase();
    }
}

// ========================================
// RETORNO PADRONIZADO PARA O SEU FLUXO
// ========================================
return {
    json: {
        // Mantém todos os dados originais intactos (id, cliente, data_inclusao...)
        ...inputData,                        

        // Dados formatados e blindados
        withDDI:    result.withDDI,          
        withoutDDI: result.withoutDDI,       
        formatted:  result.formatted,        
        isValid:    result.isValid,          
        country:    result.country,

        // Novo campo de nome
        primeiro_nome: primeiroNome          
    }
};

