WITH alvo AS (
 SELECT id FROM public.view_imoveis_leads WHERE (CASE WHEN (CASE WHEN length(regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g')) IN (10,11) THEN '55' || regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') ELSE regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') END) ~ '^55[0-9]{2}[6-9][0-9]{7}$' THEN left((CASE WHEN length(regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g')) IN (10,11) THEN '55' || regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') ELSE regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') END),4) || '9' || substring((CASE WHEN length(regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g')) IN (10,11) THEN '55' || regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') ELSE regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') END) from 5) ELSE (CASE WHEN length(regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g')) IN (10,11) THEN '55' || regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') ELSE regexp_replace(COALESCE(telefone, ''), '[^0-9]', '', 'g') END) END) = $1 ORDER BY id LIMIT 1
), atualizado AS (
 UPDATE public.view_imoveis_leads SET telefone_whatsapp = NULLIF($3, '')
 WHERE id = (SELECT id FROM alvo) RETURNING *
), criado AS (
 INSERT INTO public.view_imoveis_leads (nome, telefone, telefone_whatsapp, origem)
 SELECT NULLIF($2, ''), $1, NULLIF($3, ''), 'reativacao_base_crm_08_2026'
 WHERE NOT EXISTS (SELECT 1 FROM alvo)
 ON CONFLICT (telefone) DO UPDATE SET telefone_whatsapp = EXCLUDED.telefone_whatsapp
 RETURNING *
)
