const tipoFollowUp = $('Dados do Lead').item.json.tipo_followUp;
const nome = $('Dados do Lead').item.json.LeadNome;

// Saudação dinâmica baseada no horário de Brasília
const hora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: 'numeric', hour12: false });
const horaNum = parseInt(hora);
const saudacao = horaNum >= 5 && horaNum < 12 ? 'Bom dia' : horaNum >= 12 && horaNum < 18 ? 'Boa tarde' : 'Boa noite';

let mensagem = '';
let tipoParaAtualizar = '';

switch (tipoFollowUp) {
  case 'followUp24h':
    mensagem = `${saudacao}, ${nome}! 🤝 Conseguiu dar uma olhada nas condições que passei? Existe alguma dúvida em que eu possa auxiliar?`;
    tipoParaAtualizar = 'followUp24h';
    break;

  case 'followUp3D':
    mensagem = `${saudacao}, ${nome}! Passando pra te lembrar que é o último loteamento aberto do Novo Mundo — todos os anteriores foram 100% vendidos.\n\nSe tiver alguma dúvida ou quiser agendar uma visita, só chamar. Fico a disposição 🤝`;
    tipoParaAtualizar = 'followUp3D';
    break;

  case 'followUp5D':
    mensagem = `${nome}, ${saudacao.toLowerCase()}! Estamos com poucas unidades disponíveis na faixa que você se interessou. Se quiser garantir o seu, me avise que faço a reserva agora — sem compromisso, por 24h. 🤝`;
    tipoParaAtualizar = 'followUp5D';
    break;

  case 'finalizado':
    mensagem = `Olá, ${nome}! Rafael Lima aqui da UDI LAR 🤝 Você demonstrou interesse nos terrenos do Novo Mundo anteriormente. As vendas estão avançando e é o último loteamento aberto do bairro — com histórico de 100% vendido em todos os empreendimentos anteriores. Caso queira mais informações ou agendar uma visita, estou à disposição!`;
    tipoParaAtualizar = 'finalizado';
    break;

  default:
    mensagem = '';
    tipoParaAtualizar = '';
}

return [{
  json: {
    mensagem,
    tipoParaAtualizar
  }
}];

// === 1. CAPTURA E LIMPEZA DO TELEFONE DE BUSCA ===
let telefoneInput;
try {
  // Tenta pegar o telefone do nó anterior. Se falhar, define vazio.
  telefoneInput = $('Dados Lead').first().json.IdConversa;
} catch (error) {
  telefoneInput = ''; 
}

const limparNumero = (num) => {
  if (!num) return '';
  return num.toString().replace(/\D/g, ''); 
};

const inputLimpo = limparNumero(telefoneInput);

console.log(`Buscando telefone: ${inputLimpo}`);

// === 2. PREPARAÇÃO DOS DADOS (CORREÇÃO AQUI) ===
let leadsParaAnalisar = [];

if (items.length > 1) {
    // Cenário A: O n8n já separou os itens
    leadsParaAnalisar = items.map(item => item.json);
} else if (items.length === 1) {
    // Cenário B: O n8n trouxe tudo num item só
    const itemUnico = items[0].json;

    if (Array.isArray(itemUnico)) {
        leadsParaAnalisar = itemUnico;
    } 
    // --> AQUI ESTAVA O ERRO: A API devolve dentro de "result"
    else if (itemUnico.result && Array.isArray(itemUnico.result)) {
        leadsParaAnalisar = itemUnico.result;
    }
    // Algumas APIs devolvem dentro de "data"
    else if (itemUnico.data && Array.isArray(itemUnico.data)) {
        leadsParaAnalisar = itemUnico.data;
    }
    else {
        // Se não for lista nenhuma, tenta analisar o próprio item
        leadsParaAnalisar = [itemUnico];
    }
}

console.log(`Total de leads REAIS encontrados para análise: ${leadsParaAnalisar.length}`);

// === 3. A BUSCA ===
const leadsEncontrados = leadsParaAnalisar.filter(lead => {
  if (!lead.phones || !Array.isArray(lead.phones)) return false;

  return lead.phones.some(phone => {
    const crmLimpo = limparNumero(phone);
    if (crmLimpo === '' || inputLimpo === '') return false;

    // Verifica bidirecionalmente
    return inputLimpo.includes(crmLimpo) || crmLimpo.includes(inputLimpo);
  });
});

// === 4. RETORNO ===
if (leadsEncontrados.length > 0) {
    console.log(`SUCESSO: ${leadsEncontrados.length} lead(s) encontrado(s)!`);
    return leadsEncontrados.map(lead => ({ json: lead }));
} else {
    console.log("Nenhum lead corresponde ao filtro.");
    return [];
}

