(() => {
  const conversationId = (typeof convo !== 'undefined' && convo.id) ? convo.id : '';
  const messageId = (typeof body !== 'undefined' && body.id) ? body.id : '';

  // Contexto Temporal
  const dataHora = $now.setLocale('pt-br').toFormat("cccc, dd/MM/yyyy, HH:mm");
  const timezone = $now.zoneName; 

  // 1. Identificação do Tipo de Mídia (Checa attachments)
  let atts = [];
  if (typeof body !== 'undefined' && body.attachments && body.attachments.length) {
    atts = body.attachments;
  } else if (typeof convo !== 'undefined' && convo.messages && convo.messages[0] && convo.messages[0].attachments) {
    atts = convo.messages[0].attachments;
  }
  const hasAudio = atts.some(a => a.file_type === 'audio');
  const hasImage = atts.some(a => a.file_type === 'image');

  // Captura a legenda original do webhook (se houver)
  const legendaOriginal = (typeof body !== 'undefined' && body.content) ? body.content : '';

  // Captura as informações do anúncio do Meta (se houver) resolvendo erros silenciosamente
  let referralBody = '';
  try {
    // Usando try/catch para garantir que o n8n não dê crash se a estrutura não existir naquele instante
    referralBody = $('Webhook').item.json.body.content_attributes.whatsapp_meta_payload.messages[0].referral.body || '';
  } catch (error) {
    referralBody = '';
  }

  // 2. Busca as mensagens do Buffer (Redis)
  let rawBuffered = [];
  try {
    rawBuffered = $('buffer1').item.json.messages || [];
  } catch (e1) {
    try {
      rawBuffered = $('buffer').item.json.messages || [];
    } catch (e2) {
      rawBuffered = [];
    }
  }

  let conteudoFinal = rawBuffered.join('\n\n').trim();
  let tipoMsgMeta = 'TEXTO_CHAT';

  // 3. Lógica de Estruturação por Tipo
  if (hasAudio) {
      tipoMsgMeta = 'AUDIO_VOICE';
      conteudoFinal = `
<origem_da_mensagem>O cliente enviou um áudio.</origem_da_mensagem>
<transcricao_de_audio>
  "${conteudoFinal}"
</transcricao_de_audio>
<instrucao_ia>O texto acima é a transcrição do áudio. Responda como se tivesse ouvido a voz dele.</instrucao_ia>`.trim();
  } 
  else if (hasImage) {
      tipoMsgMeta = 'IMAGEM_CONTEUDO';
      conteudoFinal = `
<origem_da_mensagem>O cliente enviou uma imagem acompanhada de texto.</origem_da_mensagem>
<legenda_do_cliente>
  "${legendaOriginal}"
</legenda_do_cliente>
<descricao_visual_da_imagem>
  "${conteudoFinal}"
</descricao_visual_da_imagem>
<instrucao_ia>Acima está o que o cliente escreveu e a descrição técnica da imagem. Use ambos para responder com naturalidade.</instrucao_ia>`.trim();
  }

  // 4. Construção da resposta final (com tratativas de segurança pro sender)
  let nomeCliente = '';
  let telefoneCliente = '';
  try {
    nomeCliente = sender.name || '';
    telefoneCliente = sender.phone_number || '';
  } catch(e) {}

  const outputLines = [
    '### DADOS DO CLIENTE',
    `Nome: ${nomeCliente}`,
    `Telefone: ${telefoneCliente}`,
    '',
    '### CONTEXTO TEMPORAL (IMPORTANTE)',
    `Data e Hora Atual: ${dataHora}`,
    `Timezone: ${timezone}`,
    '',
    '### METADADOS DO CHAT',
    `ID_Conversa: ${conversationId}`,
    `ID_Mensagem: ${messageId}`,
    `Tipo_Mensagem: ${tipoMsgMeta}`
  ];

  // Adiciona a seção sobre o anúncio de forma dinâmica, apenas se existir
  if (referralBody && referralBody.trim() !== '') {
    outputLines.push(
      '',
      '### CONTEXTO DO ANÚNCIO (ORIGEM DO LEAD)',
      referralBody
    );
  }

  // Adiciona a última parte do payload
  outputLines.push(
    '',
    '### CONTEÚDO DA MENSAGEM PARA PROCESSAR',
    conteudoFinal || '(vazio)'
  );

  // Retorno formatado para a IA
  return outputLines.join('\n');
})()
}}

