// Obtém o primeiro item do fluxo
const item = $input.first();

if (!item || !item.json) {
  return { textoSemQuebrasNemEmojis: "" };
}

// Pega o texto (ajuste a chave 'output' se necessário)
let texto = item.json.output || "";

// 1. Remove emojis (Range Unicode)
texto = texto.replace(/[\u{1F600}-\u{1F64F}]|[\u{1F300}-\u{1F5FF}]|[\u{1F680}-\u{1F6FF}]|[\u{1F700}-\u{1F77F}]|[\u{1F780}-\u{1F7FF}]|[\u{1F800}-\u{1F8FF}]|[\u{1F900}-\u{1F9FF}]|[\u{1FA00}-\u{1FA6F}]|[\u{1FA70}-\u{1FAFF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]|[\u{FE00}-\u{FE0F}]|[\u{1F1E0}-\u{1F1FF}]/gu, "");

// 2. Remove quebras de linha excessivas
texto = texto.replace(/\n/g, " ");

// 3. Dicionário de Abreviações (Adicione as que precisar)
const abreviacoes = {
  "vc": "você",
  "vcs": "vocês",
  "tb": "também",
  "tbm": "também",
  "pq": "porque",
  "q": "que",
  "hj": "hoje",
  "blz": "beleza",
  "fds": "fim de semana",
  "mn": "mano",
  "pfv": "por favor",
  "obs": "observação",
  "msg": "mensagem",
  "add": "adicionar"
};

// Função para substituir palavras inteiras (evita substituir 'vc' dentro de 'avcd')
texto = texto.split(' ').map(palavra => {
  // Remove pontuação temporariamente para checar a palavra
  const limpa = palavra.replace(/[.,?!]/g, "").toLowerCase();
  const pontuacao = palavra.match(/[.,?!]+$/) ? palavra.match(/[.,?!]+$/)[0] : "";

  if (abreviacoes[limpa]) {
    // Retorna a palavra expandida + a pontuação original
    return abreviacoes[limpa] + pontuacao;
  }
  return palavra;
}).join(' ');

return {
  textoOriginal: item.json.output,
  textoSemQuebrasNemEmojis: texto
};

