parameters.query:
UPDATE {{ $('Parametros do Fluxo').item.json.nome_tabela_leads }}
SET ultima_mensagem = '{{ $now.setZone("America/Sao_Paulo") }}'
WHERE RIGHT(REGEXP_REPLACE(telefone::text, '\D', '', 'g'), 8)
    = RIGHT(REGEXP_REPLACE('{{ $('Webhook').item.json.body.conversation.meta.sender.phone_number.replace('+', '') }}', '\D', '', 'g'), 8);

UPDATE {{ $('Parametros do Fluxo').item.json.nome_tabela_leads }}
SET "followUp" = 'finalizado'
WHERE RIGHT(telefone::text, 8) = RIGHT('{{ $("Webhook").item.json.body.conversation.meta.sender.phone_number }}', 8);

INSERT INTO {{ $('Parametros do Fluxo').item.json.nome_tabela_leads }} (nome, telefone)
SELECT 
  '{{ $("Webhook").item.json.body.conversation.meta.sender.name }}',
  '{{ $("Webhook").item.json.body.conversation.meta.sender.phone_number.replace("+", "") }}'
WHERE NOT EXISTS (
  SELECT 1 FROM {{ $('Parametros do Fluxo').item.json.nome_tabela_leads }}
  WHERE RIGHT(REGEXP_REPLACE(telefone::text, '\D', '', 'g'), 8) = RIGHT(REGEXP_REPLACE('{{ $("Webhook").item.json.body.conversation.meta.sender.phone_number.replace("+", "") }}', '\D', '', 'g'), 8)
)
RETURNING id;

SELECT * FROM public.{{ $('Parametros do Fluxo').item.json.nome_tabela_leads }}
WHERE 
  /* 1. Limpa a coluna, mantendo apenas números */
  RIGHT(REGEXP_REPLACE(telefone::text, '\\D', '', 'g'), 8) 
  = 
  /* 2. Compara com os últimos 8 dígitos da sua entrada */
  RIGHT('{{ $("Webhook").item.json.body.conversation.meta.sender.phone_number.replace("+", "") }}', 8)
LIMIT 1;

UPDATE {{ $('Parametros do Fluxo').item.json.nome_tabela_leads }}
SET "followUp" = 'finalizado'
WHERE id = (
  SELECT id 
  FROM {{ $('Parametros do Fluxo').item.json.nome_tabela_leads }}
  WHERE RIGHT(telefone, 8) = RIGHT('{{ $('Webhook').item.json.body.conversation.meta.sender.phone_number }}', 8)
  LIMIT 1
);

